<script lang="ts">
 let {rows,columns,t,lang='de',timezone='Europe/Berlin'}:{lang?:string;timezone?:string;rows:Record<string,any>[];columns:string[];t:(key:string)=>string}=$props();
 function value(v:any,key:string){if(typeof v==='boolean')return v?'●':'—';if(v===null||v===undefined)return '—';if(typeof v==='object')return JSON.stringify(v);const text=String(v);if(/(?:_l|_ha|_kg|_ml)$/.test(key)||['cost_per_l','value','percentage'].includes(key)){const n=Number(text);if(Number.isFinite(n))return new Intl.NumberFormat(lang,{maximumFractionDigits:key==='cost_per_l'?2:key==='value'?6:key==='area_ha'?4:3}).format(n);}if(/^\d{4}-\d{2}-\d{2}T\d{2}:/.test(text))return new Intl.DateTimeFormat(lang,{dateStyle:'short',timeStyle:'short',timeZone:timezone}).format(new Date(text));return t(text);}
</script>
{#if rows.length}<div class="scroll"><table><thead><tr>{#each columns as key}<th>{t(key)}</th>{/each}</tr></thead><tbody>{#each rows as row}<tr>{#each columns as key}<td title={String(row[key]??'')}>{value(row[key],key)}</td>{/each}</tr>{/each}</tbody></table></div>{#if rows.length===500}<p class="muted">{t('listLimit')}</p>{/if}{:else}<p class="muted">{t('empty')}</p>{/if}
<style>.scroll{overflow:auto;max-height:480px}table{border-collapse:collapse;width:100%;font-size:12px;text-align:left;white-space:nowrap}th{color:#7a8573;font-size:10px;font-weight:500;letter-spacing:.3px;padding:10px 14px;border-bottom:1px solid #dce4d6;position:sticky;top:0;background:white}td{padding:13px 14px;border-bottom:1px solid #edf0e8;max-width:320px;overflow:hidden;text-overflow:ellipsis}tbody tr:hover{background:#f8faf4}</style>
